// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testRegression_property() public {
        c.seedMarket(1000);

        vm.prank(address(0xdead));
        c.getFreeKilo();

        vm.prank(c.ceoAddress());
        c.DrugDealer();

        address buyer = address(0xbeef);
        vm.deal(buyer, 1 ether);
        vm.prank(buyer);
        c.buyDrugs{value: 1 ether}();

        uint256 drugsClaimed = c.claimedDrugs(buyer);

        uint256 contractBalBefore = 0;
        uint256 drugsBought = c.calculateDrugBuy(1 ether, contractBalBefore);
        uint256 fee = c.devFee(drugsBought);
        uint256 expectedReference = drugsBought - fee;

        assertTrue(drugsClaimed == expectedReference, "Reference deducts devFee; bug does not");
    }
}
